import type { ContactKind } from '../contacts/names.ts'
import { whoGetsIt, type AssignRuleSeats } from '../followUp/assignSeats.ts'
import { whoHasReply, type OfficeHours, type TechText } from './hasRule.ts'
import { legalLines, routeReply, standingLegalLine, type LegalSend } from './legalRoute.ts'
import { answeredBefore, OFFICE_WAIT_MINUTES, pushDue, pushesFor, type Push, type PushSentRow, type ReplyHas, type ReplyLine } from './notifyRule.ts'
import type { MessageChannel, MessageDirection } from './thread.ts'

/**
 * The owner's switch (`app_settings`, R5's PR 3 makes the row, 'false'): nothing pushes until it reads 'true'. The cron
 * posts only while it is on, and the function checks it too, so a writer's call sends nothing while it is off.
 */
export const REPLY_PUSH_ON_KEY = 'messages_reply_push_on_v1'

/** The kinds whose lines push for now, the owner's call: a customer's, a lead's and a sub's. */
export const PUSH_KINDS: ReadonlySet<string> = new Set(['customer', 'lead', 'sub'])

/** A push more than this many minutes past its time is not sent, so a sweep never wakes anyone for an old line. */
export const PUSH_LATE_MAX_MINUTES = 30

/** The most lines one call plans: the sweep's cap, and the batch's. */
export const NOTIFY_LINES_MAX = 200

/** A line in, as the function reads it from `messages`. */
export interface PlanLine {
  id: string
  contactId: string
  channel: MessageChannel
  direction: MessageDirection
  at: string
  body: string
  subject?: string | null
}

/** One of our lines out to them, as the function reads it: what it was, when, and who sent it. */
export interface PlanOut {
  contactId: string
  channel: MessageChannel
  direction: MessageDirection
  at: string
  whoUserId: string | null
}

/** A contact as the plan reads it: who they are, and who has their conversation (`contacts.has_*`). */
export interface PlanContact {
  id: string
  kind: string
  /** Their name as the screens show it (`contact_display_name`). */
  name: string
  goesBy?: string | null
  hasUserId?: string | null
  hasHow?: string | null
  hasUntil?: string | null
}

/** A teammate the plan can name. */
export interface PlanUser {
  id: string
  name: string
}

export interface NotifyPlanInput {
  now: string
  lines: readonly PlanLine[]
  contacts: readonly PlanContact[]
  /** Our lines out to the same people, from before the oldest line on. */
  outs: readonly PlanOut[]
  /** The tech team's users (`messages_tech_team`: primary, helpers). */
  techs: readonly PlanUser[]
  /** The office team's users (the five roles), not archived. */
  office: readonly PlanUser[]
  seats: AssignRuleSeats
  hours: OfficeHours
  /** `messages_office_wait_minutes`; null reads the default. */
  waitMinutes: number | null
  /** The Lien desk's sends to each person, by contact id (`legalSendsFromFilings`, `legalSendsFromDemandLetters`). */
  legal: Readonly<Record<string, readonly LegalSend[]>>
  /** The pushes already sent for these lines (`notification_history.message_id`). */
  sent: ReadonlyArray<Pick<PushSentRow, 'message_id' | 'template_type'>>
}

export interface NotifyPlan {
  /** Due now: send each, then write its `pushSentRow`. */
  send: Push[]
  /** Not due yet: the office's wait. The next sweep sends it. */
  waiting: number
  /** The office's wait push, dropped because someone answered first. */
  answered: number
  /** Past `PUSH_LATE_MAX_MINUTES`, never sent. */
  late: number
}

/** How far back the sweep reads lines in: the longest a push can still be sent, with five minutes' margin. */
export function sweepSince(now: string, waitMinutes: number | null): string {
  const minutes = Math.max(0, Math.round(waitMinutes ?? OFFICE_WAIT_MINUTES)) + PUSH_LATE_MAX_MINUTES + 5
  return new Date(Date.parse(now) - minutes * 60_000).toISOString()
}

const newest = <T extends { at: string }>(rows: readonly T[], keep: (r: T) => boolean): T | null => {
  let best: T | null = null
  for (const r of rows) if (keep(r) && (!best || Date.parse(r.at) > Date.parse(best.at))) best = r
  return best
}

/** Who has one line in. */
function hasFor(line: PlanLine, contact: PlanContact, theirs: readonly PlanOut[], input: NotifyPlanInput, names: ReadonlyMap<string, string>): ReplyHas {
  const before = (r: { at: string }) => Date.parse(r.at) <= Date.parse(line.at)
  const officeIds = new Set(input.office.map((u) => u.id))
  // Whoever in the office answered them last; "here today" has no read on the server yet, so the seat decides.
  const answeredLast = newest(theirs, (o) => before(o) && o.direction === 'out' && !!o.whoUserId && officeIds.has(o.whoUserId))
  const pickId = whoGetsIt({ kind: contact.kind as ContactKind, answeredLastBy: answeredLast?.whoUserId ?? null, hereToday: new Set(), seats: input.seats })
  const pick = pickId ? { userId: pickId, name: names.get(pickId) ?? '' } : null

  const route = routeReply(line, standingLegalLine(legalLines(input.legal[contact.id] ?? [], contact.id)), pick)
  if (route) return { has: 'office', userId: route.userId, name: route.name, reason: route.reason }

  const techIds = new Set(input.techs.map((u) => u.id))
  if ((contact.hasHow === 'took' || contact.hasHow === 'handed') && contact.hasUserId) {
    const id = contact.hasUserId
    return { has: techIds.has(id) ? 'tech' : 'office', userId: id, name: names.get(id) ?? null, reason: contact.hasHow }
  }

  const text = newest(theirs, (o) => before(o) && o.direction === 'out' && o.channel === 'text' && !!o.whoUserId && techIds.has(o.whoUserId))
  const techText: TechText | null = text?.whoUserId ? { userId: text.whoUserId, name: names.get(text.whoUserId) ?? '', at: text.at } : null
  const held = contact.hasHow === 'rule' && !!techText && contact.hasUserId === techText.userId ? (contact.hasUntil ?? null) : null
  const rule = whoHasReply(
    { techText, officeUserId: pick?.userId ?? null, officeName: pick?.name ?? null, hasUntil: held, hours: input.hours, lastAutoAnswerAt: null },
    line.at,
  )
  // No after-hours answer goes until quo-send sends one, so none is said to have gone.
  return { has: rule.has, userId: rule.userId, name: rule.name, reason: rule.reason, autoAnswer: null }
}

/** The pushes the lines should send now, and what waits, what was answered first and what came too late. */
export function planReplyPushes(input: NotifyPlanInput): NotifyPlan {
  const contacts = new Map(input.contacts.map((c) => [c.id, c]))
  const names = new Map([...input.techs, ...input.office].map((u) => [u.id, u.name.trim()]))
  const officeUserIds = input.seats.customer ? [input.seats.customer] : input.office.map((u) => u.id)
  const plan: NotifyPlan = { send: [], waiting: 0, answered: 0, late: 0 }
  const lateMs = PUSH_LATE_MAX_MINUTES * 60_000
  for (const line of input.lines.slice(0, NOTIFY_LINES_MAX)) {
    const contact = contacts.get(line.contactId)
    if (!contact || line.direction !== 'in' || !PUSH_KINDS.has(contact.kind)) continue
    const theirs = input.outs.filter((o) => o.contactId === contact.id)
    const has = hasFor(line, contact, theirs, input, names)
    const reply: ReplyLine = { ...line, subject: line.subject ?? null, name: contact.name, goesBy: contact.goesBy ?? null, kind: contact.kind }
    const pushes = pushesFor(reply, has, { officeWaitMinutes: input.waitMinutes ?? undefined, officeUserIds }, input.sent)
    for (const push of pushes) {
      if (!pushDue(push, input.now)) {
        plan.waiting++
        continue
      }
      if (Date.parse(input.now) - Date.parse(push.dueAt) > lateMs) {
        plan.late++
        continue
      }
      if (push.cancelIfAnswered && answeredBefore(line, theirs, input.now)) {
        plan.answered++
        continue
      }
      plan.send.push(push)
    }
  }
  return plan
}
